const activated = $input.all().map(i => i.json);
const now = new Date();
const cdmx = new Date(now.toLocaleString('en-US', { timeZone: 'America/Mexico_City' }));
const todayStr = cdmx.getFullYear() + '-' +
  String(cdmx.getMonth() + 1).padStart(2, '0') + '-' +
  String(cdmx.getDate()).padStart(2, '0');
const hour = cdmx.getHours();
const shift = hour >= 8 && hour < 14 ? 'morning' : hour >= 14 && hour < 21 ? 'afternoon' : 'night';

return [{
  json: {
    date: todayStr,
    shift,
    activated_agents: activated.map(a => `${a.name} (${a.shift_slot})`),
    activated_count: activated.length,
    status: shift === 'night'
      ? 'night_mode_all_off'
      : activated.length > 0
        ? 'agents_on_shift'
        : 'no_schedule_found'
  }
}];

